package com.foodflow.review.entity;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="reviews",uniqueConstraints=@UniqueConstraint(columnNames={"order_id","customer_id"})) @Getter @Setter @NoArgsConstructor public class Review{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="order_id",nullable=false) private UUID orderId;@Column(name="customer_id",nullable=false) private UUID customerId;@Column(name="restaurant_id",nullable=false) private UUID restaurantId;@Column(nullable=false) private int rating;@Column(length=1000) private String comment;@Column(nullable=false) private Instant createdAt=Instant.now();}
